# Validate inputs
for arr, name in [(logp_with_result, 'logp_with_result'), (logp_call_only, 'logp_call_only'), (logp_no_call, 'logp_no_call')]:
    if not isinstance(arr, np.ndarray) or arr.ndim != 2:
        raise ValueError(f"{name} must be a 2D numpy array")
    if arr.shape[0] == 0 or arr.shape[1] == 0:
        raise ValueError(f"{name} must not be empty")
    if not np.isfinite(arr).all():
        raise ValueError(f"{name} contains non-finite values")
    if (arr > 0).any():
        raise ValueError(f"{name} contains positive values")
# Validate shape consistency
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All input arrays must have the same shape")
# Validate tau_filter
if isinstance(tau_filter, (bool, np.bool_)):
    raise ValueError("tau_filter must not be boolean")
if not np.isscalar(tau_filter):
    raise ValueError("tau_filter must be a scalar")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be finite and nonnegative")

# Compute token-wise improvement sums over the future horizon
sum_with = np.sum(logp_with_result, axis=1)
sum_call = np.sum(logp_call_only, axis=1)
sum_no = np.sum(logp_no_call, axis=1)

# Margin against using no call and using call without result
imp_no = sum_with - sum_no
imp_call = sum_with - sum_call
margins = np.minimum(imp_no, imp_call)
keep = margins > tau_filter

return keep, margins
